-- VERIFY: DEPT_ID 보유 수(기대 2963 근접) + SALES·81 부서 팀 수(기대 ~30)
SELECT COUNT(*) AS TOTAL_ROWS, COUNT(DEPT_ID) AS DEPT_FILLED FROM SCM_MGR.SCM_MST_SITE;
SELECT COUNT(DISTINCT A.DEPT_ID) AS SALES81_TEAMS
  FROM SCM_MGR.SCM_MST_SITE A
  JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO B ON A.DEPT_ID = B.DEPT_ID
 WHERE A.SITE_TYPE = 'SALES' AND A.DIVISION_ID = '81';
